(function(){
  var P = AutoJS.players()[0];
  var DC = Java.loadClass('com.merlinkitsune.astral_dice.component.ModDataComponents');
  var AS = Java.loadClass('com.merlinkitsune.astral_dice.component.AppliedStone');
  var TCU = Java.loadClass('com.merlinkitsune.astral_dice.item.card.TemporaryCardUtil');
  AutoJS.command('kill @e[type=!player,distance=..48]');
  AutoJS.command('clear @a');
  AutoJS.command('effect clear @a');
  var stack = AutoJS.stack('astral_dice:attack_card_medium', 1);
  var item = stack.getItem();
  var max = AS.defaultUses('medium');
  var out = {};
  out.maxUses = max;
  out.usesFresh = DC.CARD_USES.getOrDefault(stack, max);
  out.maxStackFresh = item.maxStackSize(stack);
  out.barVisibleFresh = item.isBarVisible(stack);
  out.foilFresh = item.isFoil(stack);
  DC.CARD_USES.set(stack, 9);
  out.usesUsed = DC.CARD_USES.getOrDefault(stack, max);
  out.maxStackUsed = item.maxStackSize(stack);
  out.barVisibleUsed = item.isBarVisible(stack);
  out.barWidthUsed = item.getBarWidth(stack);
  out.barColorUsed = item.getBarColor(stack);
  out.nbtHasCardUses = String(AutoJS.nbt(stack)).indexOf('card_uses') >= 0;
  var tmp = AutoJS.stack('astral_dice:attack_card_medium', 1);
  DC.TEMPORARY_CARD.set(tmp, true);
  out.tempIsTemporary = TCU.isTemporary(tmp);
  out.tempFoil = tmp.getItem().isFoil(tmp);
  out.tempCanDrop = tmp.getItem().onDroppedByPlayer(tmp, P);
  DC.TEMPORARY_CARD.remove(tmp);
  out.plainIsTemporary = TCU.isTemporary(tmp);
  out.plainCanDrop = tmp.getItem().onDroppedByPlayer(tmp, P);
  DC.CARD_USES.set(tmp, 2);
  out.barWidthLow = tmp.getItem().getBarWidth(tmp);
  out.barColorLow = tmp.getItem().getBarColor(tmp);
  P.getInventory().selected = 0;
  P.getInventory().setItem(0, AutoJS.stack('astral_dice:attack_card_medium', 1));
  out.useConsumed = AutoJS.use();
  var heldNow = AutoJS.held(P);
  out.heldCountAfterUse = heldNow.isEmpty() ? 0 : heldNow.getCount();
  out.heldIdAfterUse = heldNow.isEmpty() ? 'empty' : String(AutoJS.id(heldNow));
  return out;
})()

(function(){
  AutoJS.command('clear @a');
  AutoJS.command('effect clear @a');
  AutoJS.command('kill @e[type=!player,distance=..48]');
  return { cleaned: true };
})()
